-- Declared foreign keys for geo module, added where the database lacks them
-- Generated by metaphor-schema

DO $$
BEGIN
    IF to_regclass('geo.cities') IS NOT NULL AND to_regclass('geo.countries') IS NOT NULL AND NOT EXISTS (
        SELECT 1 FROM pg_constraint c
        JOIN pg_attribute a ON a.attrelid = c.conrelid AND a.attnum = ANY (c.conkey)
        WHERE c.conrelid = to_regclass('geo.cities') AND c.contype = 'f' AND a.attname = 'country_id'
    ) THEN
        ALTER TABLE geo.cities ADD CONSTRAINT fk_cities_country_id FOREIGN KEY (country_id) REFERENCES geo.countries (id) NOT VALID;
        BEGIN
            ALTER TABLE geo.cities VALIDATE CONSTRAINT fk_cities_country_id;
        EXCEPTION WHEN foreign_key_violation THEN
            RAISE NOTICE 'fk_cities_country_id left NOT VALID: stored rows of geo.cities reference missing rows';
        END;
    END IF;
END $$;

